/**
  * Tokenizer module for converting various input types to standardized string tokens.
  *
  * This module demonstrates Scala's type system with:
  * - Sealed traits for algebraic data types
  * - Option and Either for handling absence and errors
  * - Variance annotations for type flexibility
  * - Type classes for ad-hoc polymorphism
  * - Immutable case classes
  */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// ============================================================================
// Sealed Traits for Enums (Algebraic Data Types)
// ============================================================================

sealed trait TokenType
object TokenType {
  case object String extends TokenType
  case object Numeric extends TokenType
  case object Temporal extends TokenType
  case object Structured extends TokenType
  case object Binary extends TokenType
  case object Null extends TokenType
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
  * Immutable token representation.
  *
  * @param value The string value of the token
  * @param tokenType The type of token
  * @param metadata Additional metadata associated with the token
  */
case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {

  /**
    * Return new token with additional metadata.
    */
  def withMetadata(additionalMetadata: Map[String, Any]): Token = {
    copy(metadata = metadata ++ additionalMetadata)
  }

  /**
    * Return new token with additional metadata (varargs version).
    */
  def withMetadata(kvPairs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kvPairs.toMap)
  }
}

/**
  * Mutable batch of tokens - demonstrates mutable state handling in Scala.
  */
class MutableTokenBatch {
  private val tokens = mutable.ArrayBuffer.empty[Token]
  private var processed = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def getTokens: Seq[Token] = tokens.toSeq
}

// ============================================================================
// Protocol/Trait Definitions (Structural Typing)
// ============================================================================

/**
  * Any object that can be converted to a token string.
  */
trait Tokenizable {
  def toToken: String
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
  * Covariant container - can return subtypes.
  */
class TokenContainer[+T](private val items: Seq[T]) {
  def getAll: Seq[T] = items

  def mapTokens[R](func: T => R): Seq[R] = items.map(func)
}

/**
  * Contravariant sink - can accept supertypes.
  */
class TokenSink[-T] {
  private val received = mutable.ArrayBuffer.empty[Any]

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): Seq[Any] = {
    val result = received.toSeq
    received.clear()
    result
  }
}

/**
  * Invariant handler - exact type matching required.
  */
class BivariantHandler[T](private var value: T) {
  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
  * Abstract base tokenizer with generic input type.
  */
trait BaseTokenizer[T] {
  /**
    * Convert value to token.
    */
  def tokenize(value: T): Token

  /**
    * Lazy tokenization of multiple values.
    */
  def tokenizeBatch(values: Seq[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
  * Tokenizer for string and bytes types.
  *
  * @param encoding Character encoding for bytes
  * @param normalizer Optional function to normalize strings
  */
class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: Option[String => String] = None
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Right(bytes) => new String(bytes, encoding)
      case Left(str)    => str
    }

    val normalized = normalizer.map(_(strValue)).getOrElse(strValue)
    Token(normalized, TokenType.String)
  }

  // Convenience methods for direct string/bytes tokenization
  def tokenize(value: String): Token = tokenize(Left(value))
  def tokenize(value: Array[Byte]): Token = tokenize(Right(value))
}

/**
  * Tokenizer for numeric types with precision handling.
  *
  * Note: Scala doesn't allow mutable default arguments like Python.
  * We use immutable Map.empty as default instead.
  *
  * @param precision Number of decimal places for floating-point numbers
  * @param formatOptions Additional formatting options
  */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[AnyVal] {

  def tokenize(value: AnyVal): Token = {
    val (strValue, originalType) = value match {
      case d: Double =>
        (f"$d%.${precision}f", "Double")
      case f: Float =>
        (f"$f%.${precision}f", "Float")
      case i: Int =>
        (i.toString, "Int")
      case l: Long =>
        (l.toString, "Long")
      case s: Short =>
        (s.toString, "Short")
      case b: Byte =>
        (b.toString, "Byte")
      case _ =>
        (value.toString, value.getClass.getSimpleName)
    }

    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }

  // Specialized methods for type safety
  def tokenize(value: Int): Token = tokenize(value: AnyVal)
  def tokenize(value: Long): Token = tokenize(value: AnyVal)
  def tokenize(value: Float): Token = tokenize(value: AnyVal)
  def tokenize(value: Double): Token = tokenize(value: AnyVal)
  def tokenize(value: BigDecimal): Token = {
    val strValue = value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
    Token(strValue, TokenType.Numeric, Map("original_type" -> "BigDecimal"))
  }
}

/**
  * Tokenizer for date/time types.
  *
  * @param formatStr Optional custom format string
  */
class TemporalTokenizer(
    formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val (formatted, actualFormat) = value match {
      case Left(dateTime) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(isoFormat)
        (dateTime.format(fmt), fmt)
      case Right(date) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(dateFormat)
        (date.format(fmt), fmt)
    }

    Token(formatted, TokenType.Temporal)
  }

  // Convenience methods
  def tokenize(value: LocalDateTime): Token = tokenize(Left(value))
  def tokenize(value: LocalDate): Token = tokenize(Right(value))
}

// ============================================================================
// Universal Tokenizer - Handles Multiple Types
// ============================================================================

/**
  * Tokenizer that handles multiple types with runtime dispatch.
  */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
    * Dispatch to appropriate tokenizer based on runtime type.
    *
    * @param value The value to tokenize
    * @return Token representation, or None if value is null
    */
  def tokenize(value: Any): Option[Token] = {
    value match {
      case null =>
        Some(Token("NULL", TokenType.Null))

      case t: Tokenizable =>
        Some(Token(t.toToken, TokenType.Structured))

      case s: String =>
        Some(stringTokenizer.tokenize(s))

      case bytes: Array[Byte] =>
        Some(stringTokenizer.tokenize(bytes))

      case i: Int =>
        Some(numericTokenizer.tokenize(i))

      case l: Long =>
        Some(numericTokenizer.tokenize(l))

      case f: Float =>
        Some(numericTokenizer.tokenize(f))

      case d: Double =>
        Some(numericTokenizer.tokenize(d))

      case bd: BigDecimal =>
        Some(numericTokenizer.tokenize(bd))

      case dt: LocalDateTime =>
        Some(temporalTokenizer.tokenize(dt))

      case d: LocalDate =>
        Some(temporalTokenizer.tokenize(d))

      case _ =>
        // Fallback: try toString conversion
        Some(Token(value.toString, TokenType.String, Map("fallback" -> true)))
    }
  }
}

// ============================================================================
// Complex Nested Generics - Registry
// ============================================================================

/**
  * Registry with complex nested generic types.
  *
  * @tparam T The type of elements stored in containers
  */
class TokenRegistry[T] {
  private val registry = mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = mutable.ArrayBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): Seq[Option[Token]] = {
    registry.get(key) match {
      case None => Seq.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(_(item))
            .find(_.isDefined)
            .getOrElse(None)
        }
    }
  }
}

// ============================================================================
// Functor and Monad Patterns
// ============================================================================

/**
  * Functor for tokens - demonstrates functional programming patterns.
  *
  * @tparam T The wrapped value type
  */
class TokenFunctor[+T](private val value: T) {
  def map[R](func: T => R): TokenFunctor[R] = {
    new TokenFunctor(func(value))
  }

  def flatMap[R](func: T => TokenFunctor[R]): TokenFunctor[R] = {
    func(value)
  }

  def getOrElse[U >: T](default: U): U = {
    if (value == null) default else value
  }

  def get: T = value
}

/**
  * Extended monad operations.
  */
class TokenMonad[+T](value: T) extends TokenFunctor[T](value) {
  def ap[R](funcWrapped: TokenMonad[T => R]): TokenMonad[R] = {
    new TokenMonad(funcWrapped.get(this.get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
  * Represents JSON values recursively.
  */
sealed trait JsonValue
object JsonValue {
  case class JString(value: String) extends JsonValue
  case class JNumber(value: Double) extends JsonValue
  case class JBoolean(value: Boolean) extends JsonValue
  case object JNull extends JsonValue
  case class JArray(values: Seq[JsonValue]) extends JsonValue
  case class JObject(fields: Map[String, JsonValue]) extends JsonValue
}

/**
  * Tokenizer for JSON structures with recursive types.
  *
  * @param pretty Whether to use pretty printing
  */
class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = stringify(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    extractPath(value, parts.toList).map(tokenize)
  }

  private def extractPath(value: JsonValue, path: List[String]): Option[JsonValue] = {
    path match {
      case Nil => Some(value)
      case head :: tail =>
        value match {
          case JObject(fields) =>
            fields.get(head).flatMap(extractPath(_, tail))
          case JArray(values) =>
            Try(head.toInt).toOption
              .filter(idx => idx >= 0 && idx < values.length)
              .flatMap(idx => extractPath(values(idx), tail))
          case _ => None
        }
    }
  }

  private def stringify(value: JsonValue, indent: Int = 0): String = {
    val indentStr = if (pretty) "  " * indent else ""
    val newline = if (pretty) "\n" else ""

    value match {
      case JString(s)  => s""""$s""""
      case JNumber(n)  => n.toString
      case JBoolean(b) => b.toString
      case JNull       => "null"
      case JArray(values) =>
        if (values.isEmpty) "[]"
        else {
          val items = values.map(v => s"$indentStr  ${stringify(v, indent + 1)}")
          s"[$newline${items.mkString(s",$newline")}$newline$indentStr]"
        }
      case JObject(fields) =>
        if (fields.isEmpty) "{}"
        else {
          val items = fields.map { case (k, v) =>
            s"""$indentStr  "$k": ${stringify(v, indent + 1)}"""
          }
          s"{$newline${items.mkString(s",$newline")}$newline$indentStr}"
        }
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
  * Basic tokenizer that splits text by whitespace.
  *
  * @param lowercase Convert all tokens to lowercase
  * @param minLength Minimum token length (shorter tokens are filtered out)
  * @param maxLength Maximum token length (longer tokens are truncated)
  * @param stripPunctuation Remove leading/trailing punctuation from tokens
  */
class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse
        .dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength match {
      case Some(max) if processed.length > max =>
        processed = processed.take(max)
      case _ =>
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
    * Split text by whitespace and return list of tokens.
    *
    * @param text Input text to tokenize
    * @return Sequence of Token objects
    */
  def tokenize(text: String): Seq[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toSeq
  }

  /**
    * Split text by whitespace and return list of token strings.
    *
    * @param text Input text to tokenize
    * @return Sequence of token strings
    */
  def tokenizeToStrings(text: String): Seq[String] = {
    tokenize(text).map(_.value)
  }

  /**
    * Tokenize text and return tokens with character positions.
    *
    * @param text Input text to tokenize
    * @return Sequence of tuples (token_string, start_pos, end_pos)
    */
  def tokenizeWithPositions(text: String): Seq[(String, Int, Int)] = {
    val result = mutable.ArrayBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toSeq
  }

  /**
    * Return the number of tokens in the text.
    */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
  * Fluent builder for creating tokenizers.
  *
  * @tparam T The input type for the tokenizer
  */
class TokenizerBuilder[T] {
  private val normalizers = mutable.ArrayBuffer.empty[String => String]
  private val validators = mutable.ArrayBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kvPairs: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= kvPairs
    this
  }

  /**
    * Build the final tokenizer function.
    *
    * @return A function that converts T to Token
    */
  def build(): T => Either[String, Token] = {
    val normalizersCopy = normalizers.toSeq
    val validatorsCopy = validators.toSeq
    val metadataCopy = metadata.toMap

    (value: T) => {
      // Validate
      validatorsCopy.find(!_(value)) match {
        case Some(_) => Left(s"Validation failed for $value")
        case None =>
          // Convert to string
          var strValue = value.toString

          // Normalize
          normalizersCopy.foreach { normalizer =>
            strValue = normalizer(strValue)
          }

          Right(Token(strValue, TokenType.String, metadataCopy))
      }
    }
  }
}

// ============================================================================
// Companion Objects and Factory Methods
// ============================================================================

object Token {
  /**
    * Create a string token.
    */
  def string(value: String, metadata: Map[String, Any] = Map.empty): Token = {
    Token(value, TokenType.String, metadata)
  }

  /**
    * Create a numeric token.
    */
  def numeric(value: String, metadata: Map[String, Any] = Map.empty): Token = {
    Token(value, TokenType.Numeric, metadata)
  }

  /**
    * Create a null token.
    */
  def nullToken: Token = {
    Token("NULL", TokenType.Null)
  }
}

object Tokenizer {
  /**
    * Create a universal tokenizer instance.
    */
  def universal: UniversalTokenizer = new UniversalTokenizer()

  /**
    * Create a whitespace tokenizer with default settings.
    */
  def whitespace: WhitespaceTokenizer = new WhitespaceTokenizer()

  /**
    * Create a builder for custom tokenizers.
    */
  def builder[T]: TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

